(function(){
  'use strict';
  const CATALOG=window.KINOSIS_CATALOG||{mode:'demo',updatedAt:'missing',movies:[],sections:{trending:[],theatres:[],streaming:[],rated:[],art:[]},featured:null};
  const CLOUD=window.KINOSIS_CLOUD||null;
  const ART=window.KINOSIS_ART||{classify:()=>({isArt:false,score:0,reasons:[]})};
  const UI=window.KINOSIS_UI;
  const movieMap=new Map((CATALOG.movies||[]).map(m=>[String(m.id),normalizeMovieRecord(m)]));
  const theatreIds=new Set((CATALOG.sections?.theatres||[]).map(m=>String(m.id)));
  const STORAGE_KEY='kinosis.mvp.v2.state';
  const LEGACY_STORAGE_KEY='film.mvp.v2.state';
  const MIGRATION_PREFIX='kinosis.legacy.migrated.';
  const PROVIDERS=[
    {key:'Netflix',label:'Netflix',aliases:['Netflix','Netflix Standard with Ads']},
    {key:'TVING',label:'TVING',aliases:['TVING']},
    {key:'Coupang Play',label:'Coupang Play',aliases:['Coupang Play']},
    {key:'Disney+',label:'Disney+',aliases:['Disney Plus','Disney+']},
    {key:'WATCHA',label:'WATCHA',aliases:['Watcha','WATCHA']},
    {key:'Wavve',label:'Wavve',aliases:['wavve','Wavve']},
    {key:'Apple TV Plus',label:'Apple TV+',aliases:['Apple TV Plus','Apple TV+']},
    {key:'Collectio',label:'콜렉티오',aliases:['Collectio','COLLECTIO','콜렉티오'],manualOnly:true}
  ];
  let activeView='discover',previousView='discover',detailMovieId=null;
  let authReady=false,currentUser=null,currentRole='guest',suppressCloudSync=true,syncTimer=null;
  let syncState={status:'guest',lastSyncedAt:null,message:''};
  let libraryMode='home',libraryView='grid',myMode='overview',libraryQueryTimer=null;
  let libraryFilter={q:'',sort:'recent',status:'all',rating:'all',availability:'all',genre:'all',decade:'all',arthouse:'all'};
  let calendarCursor=new Date();
  let searchTimer=null,searchAbort=null,searchSerial=0,searchComposing=false,searchPurpose='normal';
  let liveSearchState={query:'',status:'idle',results:[],message:''};
  let curations=[],curationStatus='idle',adminSelectedId=null,adminDraft=null;
  const LIVE_SEARCH_MIN_CHARS=2,LIVE_SEARCH_DEBOUNCE=300;

  function icon(name){return `<svg class="ui-icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;}
  function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
  function isoDate(date){return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,10);}
  function fmtRuntime(n){if(!n)return'';const h=Math.floor(n/60),m=n%60;return h?`${h}h ${m}m`:`${m}m`;}
  function formatDate(value){if(!value)return'—';try{return new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'short',day:'numeric'}).format(new Date(value));}catch{return value;}}
  function formatDateTime(value){if(!value)return'없음';try{return new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch{return value;}}
  function normalizeProviderName(value){return String(value||'').toLowerCase().replace(/[^a-z0-9가-힣]+/g,'');}
  function providerConfigForName(name){const n=normalizeProviderName(name);return PROVIDERS.find(p=>[p.key,p.label,...(p.aliases||[])].some(v=>normalizeProviderName(v)===n))||null;}
  function normalizeMovieRecord(m){if(!m||m.id==null)return null;return {...m,id:String(m.id),title:m.title||m.originalTitle||'Untitled',originalTitle:m.originalTitle||'',year:m.year||String(m.releaseDate||'').slice(0,4)||null,providers:Array.isArray(m.providers)?m.providers:[],genres:Array.isArray(m.genres)?m.genres:[],source:m.source||'catalog'};}
  function poster(m){return m?.posterUrl||'./icons/icon.svg';}
  function backdrop(m){return m?.heroBackdropUrl||m?.backdropUrl||m?.posterUrl||'./icons/icon.svg';}
  function uniqueById(list){const seen=new Set();return(list||[]).filter(x=>x&&!seen.has(String(x.id))&&seen.add(String(x.id)));}
  function movie(id){return movieMap.get(String(id))||state.movieCache?.[String(id)]||null;}
  function rememberMovie(m,{persist=false}={}){const n=normalizeMovieRecord(m);if(!n)return null;movieMap.set(String(n.id),n);if(persist){state.movieCache=state.movieCache||{};state.movieCache[String(n.id)]=n;}return n;}
  function genreNames(m){return(m?.genres||[]).map(g=>typeof g==='string'?g:g?.name).filter(Boolean);}
  function artInfo(m){return ART.classify(m,{threshold:window.KINOSIS_CONFIG?.arthouse?.threshold||36});}
  function isArthouse(m){return!!artInfo(m).isArt;}
  function artPool(){return uniqueById([...(CATALOG.sections?.art||[]),...(CATALOG.movies||[])]).filter(isArthouse);}
  function isInTheatres(m){return theatreIds.has(String(m?.id));}
  function providerTypeLabel(type){return({subscription:'구독',free:'무료',ads:'광고 포함',rent:'대여',buy:'구매'})[type]||type;}

  function initialState(){return{profile:{name:'',handle:'',bio:'내 영화생활을 기록합니다.'},subscriptions:[],settings:{lastExportAt:null},meta:{modifiedAt:null,lastSyncedAt:null,dirtySince:null},movieCache:{},library:{},logs:[],collections:[]};}
  function readJson(key){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):null;}catch{return null;}}
  function normalizeState(parsed){const base=initialState();parsed=parsed||{};return Object.assign(base,parsed,{profile:Object.assign(base.profile,parsed.profile||{}),settings:Object.assign(base.settings,parsed.settings||{}),meta:Object.assign(base.meta,parsed.meta||{}),movieCache:Object.assign({},parsed.movieCache||{}),library:Object.assign({},parsed.library||{}),logs:Array.isArray(parsed.logs)?parsed.logs:[],collections:Array.isArray(parsed.collections)?parsed.collections:[],subscriptions:Array.isArray(parsed.subscriptions)?parsed.subscriptions:[]});}
  function legacyState(){return normalizeState(readJson(STORAGE_KEY)||readJson(LEGACY_STORAGE_KEY));}
  function userCacheKey(){return currentUser?.id?`kinosis.user.${currentUser.id}.state.v1`:null;}
  function hasPersonalData(v){return!!(Object.keys(v?.library||{}).length||v?.logs?.length||v?.collections?.length||v?.subscriptions?.length||Object.keys(v?.movieCache||{}).length);}
  function mergeImport(base,incoming){const out=normalizeState(base),src=normalizeState(incoming);out.profile=Object.assign({},out.profile,src.profile);out.library=Object.assign({},out.library,src.library);out.movieCache=Object.assign({},out.movieCache,src.movieCache);out.logs=[...new Map([...(out.logs||[]),...(src.logs||[])].map(x=>[String(x.id),x])).values()];out.collections=[...new Map([...(out.collections||[]),...(src.collections||[])].map(x=>[String(x.id),x])).values()];out.subscriptions=[...new Set([...(out.subscriptions||[]),...(src.subscriptions||[])])];out.meta.modifiedAt=new Date().toISOString();out.meta.dirtySince=out.meta.modifiedAt;return out;}
  let state=initialState();
  function isSignedIn(){return!!currentUser;}
  function isAdmin(){return currentRole==='admin'||currentRole==='editor';}
  function persistLocalCache(){if(isSignedIn()){const key=userCacheKey();if(key)localStorage.setItem(key,JSON.stringify(state));}}
  function saveState({sync=true,mark=true}={}){if(mark){state.meta=state.meta||{};state.meta.modifiedAt=new Date().toISOString();state.meta.dirtySince=state.meta.dirtySince||state.meta.modifiedAt;}persistLocalCache();if(sync&&isSignedIn()&&!suppressCloudSync)scheduleCloudSync();}
  function rememberCachedMovies(){Object.values(state.movieCache||{}).forEach(m=>rememberMovie(m));}
  function scheduleCloudSync(delay=500){clearTimeout(syncTimer);syncState.status='pending';renderAccountChrome();syncTimer=setTimeout(pushCloudState,delay);}
  async function pushCloudState(){if(!isSignedIn()||!CLOUD)return;clearTimeout(syncTimer);syncState.status=navigator.onLine?'syncing':'offline';renderAccountChrome();if(!navigator.onLine)return;try{const row=await CLOUD.writeUserState(JSON.parse(JSON.stringify(state)));const stamp=row?.updated_at||new Date().toISOString();state.meta.lastSyncedAt=stamp;state.meta.dirtySince=null;persistLocalCache();syncState={status:'online',lastSyncedAt:stamp,message:''};}catch(error){syncState={status:'offline',lastSyncedAt:state.meta?.lastSyncedAt||null,message:error.message||'Sync failed'};}renderAccountChrome();if(activeView==='my'&&myMode==='settings')renderMy();}
  async function hydrateSignedInUser(){if(!isSignedIn()||!CLOUD)return;suppressCloudSync=true;syncState.status='syncing';try{const [cloud,role]=await Promise.all([CLOUD.readUserState(),CLOUD.readMyRole().catch(()=> 'user')]);currentRole=role||'user';const cached=normalizeState(readJson(userCacheKey()));let next=cloud?.payload?normalizeState(cloud.payload):(hasPersonalData(cached)?cached:initialState());const cloudTime=Date.parse(cloud?.updated_at||0)||0,cacheTime=Date.parse(cached.meta?.modifiedAt||0)||0;if(hasPersonalData(cached)&&cacheTime>cloudTime)next=mergeImport(next,cached);const old=legacyState(),migrationKey=MIGRATION_PREFIX+currentUser.id;if(hasPersonalData(old)&&!localStorage.getItem(migrationKey)){const count=Object.keys(old.library||{}).length;const answer=await UI.ask({eyebrow:'LOCAL DATA',title:'이전 기록을 가져올까요?',message:`이 브라우저에서 이전 KINOSIS 기록 ${count}편을 찾았습니다. 현재 계정에 병합할 수 있습니다.`,confirmText:'가져오기'});if(answer.confirmed)next=mergeImport(next,old);localStorage.setItem(migrationKey,new Date().toISOString());}state=normalizeState(next);rememberCachedMovies();state.meta.lastSyncedAt=cloud?.updated_at||state.meta.lastSyncedAt||null;persistLocalCache();suppressCloudSync=false;if(!cloud||state.meta.dirtySince)await pushCloudState();else syncState={status:'online',lastSyncedAt:state.meta.lastSyncedAt,message:''};}catch(error){const cached=readJson(userCacheKey());state=normalizeState(cached||initialState());rememberCachedMovies();suppressCloudSync=false;syncState={status:'offline',lastSyncedAt:state.meta?.lastSyncedAt||null,message:error.message||'Cloud unavailable'};}await refreshCurations();renderAll();}

  function lib(id){return state.library[String(id)]||null;}
  function ensureLib(id){const k=String(id);if(!state.library[k])state.library[k]={savedAt:new Date().toISOString(),watched:false,watchlist:false,favorite:false,rating:null,review:''};return state.library[k];}
  function allSavedMovies(){return Object.keys(state.library).map(movie).filter(Boolean);}
  function latestLogs(){return[...state.logs].sort((a,b)=>String(b.watchedAt).localeCompare(String(a.watchedAt)));}
  function latestUniqueMovies(){const seen=new Set();return latestLogs().map(l=>movie(l.movieId)).filter(m=>m&&!seen.has(String(m.id))&&seen.add(String(m.id)));}
  function isSubscriptionEnabled(key){if(!isSignedIn())return false;const n=normalizeProviderName(key);return(state.subscriptions||[]).some(v=>normalizeProviderName(v)===n);}
  function isSubscribedProvider(name){const cfg=providerConfigForName(name);return cfg?isSubscriptionEnabled(cfg.key):isSubscriptionEnabled(name);}
  function subscriptionProviders(m){return(m?.providers||[]).filter(p=>p.type==='subscription');}
  function availableOnMine(m){return subscriptionProviders(m).some(p=>isSubscribedProvider(p.name));}
  function myStreamingMovies(){return(CATALOG.movies||[]).filter(availableOnMine);}
  function watchlistAvailable(){return allSavedMovies().filter(m=>lib(m.id)?.watchlist&&availableOnMine(m));}
  function providerBadges(m,max=2){const providers=[...subscriptionProviders(m)].sort((a,b)=>(isSubscribedProvider(b.name)?1:0)-(isSubscribedProvider(a.name)?1:0));return providers.slice(0,max).map(p=>`<span class="provider-icon" title="${escapeHtml(providerConfigForName(p.name)?.label||p.name)}"><img src="${escapeHtml(p.logoUrl||'./icons/icon.svg')}" alt=""/></span>`).join('');}
  function availabilityBadges(m){const ott=providerBadges(m,2);const cinema=isInTheatres(m)?`<span class="cinema-icon-badge" title="현재 극장 상영 목록">${icon('cinema')}</span>`:'';return `<div class="availability-stack">${cinema}${ott}</div>`;}
  function canUseLiveApi(){return location.protocol==='http:'||location.protocol==='https:';}
  async function apiJson(path,{signal}={}){const response=await fetch(path,{headers:{Accept:'application/json'},signal,cache:'no-store'});let data=null;try{data=await response.json();}catch{}if(!response.ok)throw new Error(data?.error||`API ${response.status}`);return data;}
  async function fetchLiveSearch(query,{signal}={}){const data=await apiJson(`/api/movie-search?q=${encodeURIComponent(query)}`,{signal});return(data.results||[]).map(m=>rememberMovie({...m,source:'tmdb-live',detailLoaded:false})).filter(Boolean);}
  async function fetchMovieDetail(id,{persist=false}={}){const data=await apiJson(`/api/movie-detail?id=${encodeURIComponent(id)}`);const detailed=rememberMovie({...data,source:'tmdb-live',detailLoaded:true},{persist});if(persist)saveState();return detailed;}
  async function ensureMovieDetail(id,{persist=false}={}){let current=movie(id);if(!current)return null;const needs=current.source==='tmdb-live'&&!current.detailLoaded;if(needs&&canUseLiveApi()){try{current=await fetchMovieDetail(id,{persist});}catch(error){console.warn('detail fallback',error);}}else if(persist&&!CATALOG.movies?.some(m=>String(m.id)===String(id))){rememberMovie(current,{persist:true});saveState();}return current;}

  function gateHtml(area){return `<div class="gate-card"><div class="gate-card-inner"><div class="gate-icon">${icon('lock')}</div><p class="eyebrow">ACCOUNT REQUIRED</p><h1>${escapeHtml(area)}</h1><p>개인 기록은 계정과 연결됩니다. 로그인하면 같은 Library와 MY를 PC·모바일에서 이어서 사용할 수 있습니다.</p><button class="primary-button" data-open-auth>로그인하고 시작하기</button></div></div>`;}
  function requireAuth(message='로그인하면 이 기능을 사용할 수 있습니다.'){if(isSignedIn())return true;UI.toast(message);UI.showDialog('authDialog');return false;}
  function renderAccountChrome(){const avatar=document.getElementById('topAvatar');if(!avatar)return;if(isSignedIn()){const label=currentUser?.user_metadata?.full_name||currentUser?.user_metadata?.name||currentUser?.email||'U';avatar.textContent=String(label).trim()[0]?.toUpperCase()||'U';}else avatar.textContent='K';document.querySelectorAll('[data-nav="library"],[data-nav="my"]').forEach(el=>el.classList.toggle('nav-locked',!isSignedIn()));}

  function heroProviders(m){const rank={subscription:0,free:1,ads:2,rent:3,buy:4},seen=new Set();return[...(m?.providers||[])].sort((a,b)=>(rank[a.type]??9)-(rank[b.type]??9)).filter(p=>{const k=normalizeProviderName(providerConfigForName(p.name)?.key||p.name||p.id);if(seen.has(k))return false;seen.add(k);return true;}).slice(0,4);}
  function heroTitleClass(title){const n=[...String(title||'').replace(/\s/g,'')].length;return n>24?'hero-title is-xlong':n>15?'hero-title is-long':'hero-title';}
  function renderHero(m){const el=document.getElementById('hero');if(!m){el.innerHTML='<div class="empty-state">카탈로그를 불러오지 못했습니다.</div>';return;}const providers=heroProviders(m);const title=m.logoUrl?`<div class="hero-title-wrap"><img class="hero-title-logo" src="${escapeHtml(m.logoUrl)}" alt="${escapeHtml(m.title)}" onerror="this.style.display='none';this.nextElementSibling.hidden=false"><h2 class="${heroTitleClass(m.title)}" hidden>${escapeHtml(m.title)}</h2></div>`:`<h2 class="${heroTitleClass(m.title)}">${escapeHtml(m.title)}</h2>`;el.innerHTML=`<img class="hero-bg" src="${escapeHtml(backdrop(m))}" alt=""><div class="hero-content"><div class="hero-badges"><span class="mini-badge accent">FEATURED</span>${isInTheatres(m)?'<span class="mini-badge">IN THEATRES</span>':''}</div>${title}<div class="hero-meta"><span>${escapeHtml(m.director||'Director —')}</span><span>·</span><span>${m.year||'—'}</span>${m.runtime?`<span>·</span><span>${fmtRuntime(m.runtime)}</span>`:''}</div><div class="hero-watch"><span class="hero-watch-label">WHERE TO WATCH</span><div class="hero-provider-list">${providers.map(p=>`<span class="hero-provider ${p.type==='subscription'&&isSubscribedProvider(p.name)?'is-mine':''}" title="${escapeHtml((providerConfigForName(p.name)?.label||p.name)+' · '+providerTypeLabel(p.type))}"><img src="${escapeHtml(p.logoUrl||'./icons/icon.svg')}" alt=""></span>`).join('')}</div>${isInTheatres(m)?`<span class="hero-cinema">${icon('cinema')} 극장 상영</span>`:''}</div></div>`;el.onclick=()=>openMovie(m.id);}

  function card(m,variant='discover'){if(!m)return'';const l=lib(m.id),compact=variant==='library';return `<article class="movie-card ${compact?'library-movie-card':''}" data-movie="${escapeHtml(m.id)}" tabindex="0" aria-label="${escapeHtml(m.title)} 상세보기"><div class="poster-wrap"><img src="${escapeHtml(poster(m))}" alt="${escapeHtml(m.title)} 포스터" loading="lazy" onerror="this.style.display='none'"><div class="poster-fallback">${escapeHtml(m.title)}</div>${availabilityBadges(m)}<div class="card-overlay">${isSignedIn()?`<div class="quick-actions"><button class="tiny-button ${l?'':'accent'}" data-action="save" data-id="${m.id}">${l?'✓':'＋'}</button><button class="tiny-button" data-action="log" data-id="${m.id}">LOG</button></div>`:''}</div></div><div class="card-info"><p class="card-title">${escapeHtml(m.title)}</p><div class="card-meta"><span>${m.year||'—'}</span>${availableOnMine(m)?'<span class="mine-dot"></span><span>내 구독</span>':''}</div></div></article>`;}
  function rowSection(title,subtitle,movies,limit=12,variant='discover'){const list=uniqueById(movies||[]).slice(0,limit);return `<section class="content-section"><div class="section-head"><div><h2>${escapeHtml(title)}</h2>${subtitle?`<p>${escapeHtml(subtitle)}</p>`:''}</div></div>${list.length?`<div class="poster-row">${list.map(m=>card(m,variant)).join('')}</div>`:`<div class="empty-state"><b>아직 표시할 영화가 없습니다.</b><span>데이터가 갱신되면 이 섹션도 자동으로 채워집니다.</span></div>`}</section>`;}
  function curationMovies(c){return(c?.items||[]).map(x=>rememberMovie(x.movie)).filter(Boolean);}
  function editorialSection(c){const list=curationMovies(c);if(!list.length)return'';return `<section class="editorial-section"><div class="editorial-head"><div><p class="eyebrow">KINOSIS CURATION</p><h2>${escapeHtml(c.title)}</h2><p>${escapeHtml(c.subtitle||c.description||'')}</p></div></div><div class="editorial-strip">${list.map(m=>`<article class="editorial-movie-card" data-movie="${m.id}" tabindex="0"><img src="${escapeHtml(m.backdropUrl||m.posterUrl||poster(m))}" alt=""><h3 class="editorial-card-title">${escapeHtml(m.title)}</h3>${availabilityBadges(m)}</article>`).join('')}</div></section>`;}
  function validCuration(c,surface){const now=Date.now(),start=c.starts_at?Date.parse(c.starts_at):0,end=c.ends_at?Date.parse(c.ends_at):Infinity;return c.status==='published'&&(c.surface===surface||c.surface==='both')&&now>=start&&now<=end;}
  function publishedCurations(surface){return curations.filter(c=>validCuration(c,surface));}
  function fallbackCuration(surface){const pool=surface==='arthouse'?artPool():uniqueById(CATALOG.sections?.trending||[]);return{title:surface==='arthouse'?'KINOSIS Arthouse Selection':'KINOSIS Selects',subtitle:surface==='arthouse'?'작가와 영화사적 맥락을 중심으로 고른 작품.':'이번 주 KINOSIS가 먼저 보여주고 싶은 영화.',description:'',surface,status:'published',items:pool.slice(0,7).map((m,i)=>({position:i,tmdbId:String(m.id),movie:m}))};}
  function myStreamingSection(title='내 구독 서비스에서',source=null){if(!isSignedIn())return'';const list=(source||myStreamingMovies()).filter(availableOnMine);return list.length?rowSection(title,'내가 이미 구독 중인 서비스에서 볼 수 있는 영화.',list,12):'';}
  function renderDiscover(){renderHero(CATALOG.featured||(CATALOG.sections?.trending||[])[0]);const curated=publishedCurations('discover')[0]||fallbackCuration('discover');let html='';html+=rowSection('지금 극장에서','현재 한국 상영 목록. 포스터의 필름 아이콘으로도 표시합니다.',CATALOG.sections?.theatres||[],12);if(isSignedIn())html+=myStreamingSection();else html+=rowSection('스트리밍에서','대한민국 지역 구독형 스트리밍 제공작.',CATALOG.sections?.streaming||[],12);html+=editorialSection(curated);html+=rowSection('이번 주 주목할 영화','현재 트렌드와 신작을 한곳에서 봅니다.',CATALOG.sections?.trending||[],12);html+=rowSection('높은 평가를 받은 영화','TMDB 사용자 평가 기반.',CATALOG.sections?.rated||[],12);document.getElementById('discoverContent').innerHTML=html;}
  function renderArthouse(){const art=artPool(),curated=publishedCurations('arthouse');const feature=curated[0]||fallbackCuration('arthouse'),heroMovie=curationMovies(feature)[0]||art[0]||CATALOG.featured;const hero=document.getElementById('arthouseHero');if(heroMovie){hero.innerHTML=`<img class="arthouse-hero-bg" src="${escapeHtml(backdrop(heroMovie))}" alt=""><div class="arthouse-hero-content"><span class="editorial-kicker">FEATURED CURATION</span><h2>${escapeHtml(feature.title)}</h2><p>${escapeHtml(feature.description||feature.subtitle||'KINOSIS가 편집한 Arthouse 큐레이션.')}</p></div>`;hero.onclick=()=>{const sec=document.querySelector('#arthouseContent .editorial-section');sec?.scrollIntoView({behavior:'smooth'});};}let html=editorialSection(feature);const artTheatres=(CATALOG.sections?.theatres||[]).filter(isArthouse);html+=rowSection('지금 아트시네마에서','현재 상영 목록 중 Arthouse 후보.',artTheatres,12);for(const c of curated.slice(1,3))html+=editorialSection(c);html+=rowSection("Director's Archive · 후보",'작가 중심 감독 시드를 바탕으로 모은 작품.',art.filter(m=>artInfo(m).reasons?.some(r=>r.includes('감독'))),14);html+=rowSection('From the Archive','1990년 이전 영화사적 캐논과 고전 후보.',art.filter(m=>Number(m.year||0)>0&&Number(m.year)<1990),14);if(isSignedIn())html+=myStreamingSection('내 구독에서 볼 수 있는 Arthouse',art);document.getElementById('arthouseContent').innerHTML=html;}

  function renderCollectionsSide(){const el=document.getElementById('collectionSideLinks');if(el)el.innerHTML=state.collections.map(c=>`<button class="side-link" data-collection="${escapeHtml(c.id)}">${icon('folder')}${escapeHtml(c.name)}</button>`).join('');}
  function libraryStats(){const films=allSavedMovies(),watched=films.filter(m=>lib(m.id)?.watched).length,watchlist=films.filter(m=>lib(m.id)?.watchlist).length,favorites=films.filter(m=>lib(m.id)?.favorite).length;return{films:films.length,watched,watchlist,favorites};}
  function collectionCards(){const dynamic=`<article class="collection-card" data-dynamic="my-streaming"><p class="eyebrow">DYNAMIC</p><h3>Watchlist · 내 구독</h3><p>${watchlistAvailable().length} films · 자동 갱신</p></article>`;return dynamic+state.collections.map(c=>`<article class="collection-card" data-collection-card="${escapeHtml(c.id)}"><p class="eyebrow">COLLECTION</p><h3>${escapeHtml(c.name)}</h3><p>${c.movieIds.filter(id=>movie(id)).length} films</p></article>`).join('');}
  function libraryHeader(title,summary){return `<header class="library-header"><div><p class="eyebrow">LIBRARY</p><h1>${escapeHtml(title)}</h1><p>${escapeHtml(summary)}</p></div><button class="secondary-button" id="librarySearchButton">${icon('search')} 영화 찾기</button></header>`;}
  function renderLibraryHome(){const s=libraryStats(),recent=latestUniqueMovies(),upnext=watchlistAvailable(),favorites=allSavedMovies().filter(m=>lib(m.id)?.favorite);return `${libraryHeader('내 영화 서가','저장한 영화를 다시 찾고, 관리하고, 다음 감상을 고르는 공간입니다.')}<div class="library-stats"><div class="library-stat"><strong>${s.films}</strong><span>FILMS</span></div><div class="library-stat"><strong>${s.watched}</strong><span>WATCHED</span></div><div class="library-stat"><strong>${s.watchlist}</strong><span>WATCHLIST</span></div><div class="library-stat"><strong>${s.favorites}</strong><span>FAVORITES</span></div></div>${rowSection('최근 본 영화','최근 감상 기록 순.',recent,9,'library')}${rowSection('다음에 볼 영화','Watchlist 중 내 구독 서비스에서 바로 볼 수 있는 영화.',upnext,9,'library')}<section class="content-section"><div class="section-head"><div><h2>Collections</h2><p>직접 만든 묶음과 자동 컬렉션.</p></div></div><div class="collection-grid">${collectionCards()}</div></section>${favorites.length?rowSection('Favorites','다시 꺼내보고 싶은 영화.',favorites,9,'library'):''}`;}
  function filterLibrary(list){let out=[...list];const q=libraryFilter.q.trim().toLocaleLowerCase('ko-KR');if(q)out=out.filter(m=>[m.title,m.originalTitle,m.director,...genreNames(m)].filter(Boolean).join(' ').toLocaleLowerCase('ko-KR').includes(q));if(libraryFilter.status==='watched')out=out.filter(m=>lib(m.id)?.watched);else if(libraryFilter.status==='unwatched')out=out.filter(m=>!lib(m.id)?.watched);else if(libraryFilter.status==='watchlist')out=out.filter(m=>lib(m.id)?.watchlist);else if(libraryFilter.status==='favorite')out=out.filter(m=>lib(m.id)?.favorite);if(libraryFilter.rating!=='all')out=out.filter(m=>(lib(m.id)?.rating||0)>=Number(libraryFilter.rating));if(libraryFilter.availability==='mine')out=out.filter(availableOnMine);if(libraryFilter.genre!=='all')out=out.filter(m=>genreNames(m).includes(libraryFilter.genre));if(libraryFilter.arthouse==='arthouse')out=out.filter(isArthouse);if(libraryFilter.decade!=='all'){const d=Number(libraryFilter.decade);out=out.filter(m=>Number(m.year)>=d&&Number(m.year)<d+10);}if(libraryFilter.sort==='title')out.sort((a,b)=>a.title.localeCompare(b.title,'ko'));else if(libraryFilter.sort==='rating')out.sort((a,b)=>(lib(b.id)?.rating||0)-(lib(a.id)?.rating||0));else if(libraryFilter.sort==='year')out.sort((a,b)=>(b.year||0)-(a.year||0));else if(libraryFilter.sort==='watched')out.sort((a,b)=>String((state.logs.findLast?.(l=>String(l.movieId)===String(b.id))||{})?.watchedAt||'').localeCompare(String((state.logs.findLast?.(l=>String(l.movieId)===String(a.id))||{})?.watchedAt||'')));else out.sort((a,b)=>String(lib(b.id)?.savedAt||'').localeCompare(String(lib(a.id)?.savedAt||'')));return out;}
  function libraryToolbar(list){const genres=[...new Set(list.flatMap(genreNames))].sort((a,b)=>a.localeCompare(b,'ko')),decades=[...new Set(list.map(m=>Math.floor(Number(m.year||0)/10)*10).filter(Boolean))].sort((a,b)=>b-a);return `<div class="library-toolbar"><input id="libraryQuery" value="${escapeHtml(libraryFilter.q)}" placeholder="제목 · 감독 · 장르"><select id="libraryStatus"><option value="all">상태 전체</option><option value="watched" ${libraryFilter.status==='watched'?'selected':''}>본 영화</option><option value="unwatched" ${libraryFilter.status==='unwatched'?'selected':''}>안 본 영화</option><option value="watchlist" ${libraryFilter.status==='watchlist'?'selected':''}>Watchlist</option><option value="favorite" ${libraryFilter.status==='favorite'?'selected':''}>Favorites</option></select><select id="libraryAvailability"><option value="all">감상처 전체</option><option value="mine" ${libraryFilter.availability==='mine'?'selected':''}>내 구독에서 가능</option></select><select id="libraryGenre"><option value="all">장르 전체</option>${genres.map(g=>`<option ${libraryFilter.genre===g?'selected':''}>${escapeHtml(g)}</option>`).join('')}</select><select id="libraryDecade"><option value="all">연대 전체</option>${decades.map(d=>`<option value="${d}" ${String(libraryFilter.decade)===String(d)?'selected':''}>${d}s</option>`).join('')}</select><select id="libraryArthouse"><option value="all">전체 영화</option><option value="arthouse" ${libraryFilter.arthouse==='arthouse'?'selected':''}>Arthouse</option></select><select id="librarySort"><option value="recent" ${libraryFilter.sort==='recent'?'selected':''}>최근 추가</option><option value="watched" ${libraryFilter.sort==='watched'?'selected':''}>최근 감상</option><option value="title" ${libraryFilter.sort==='title'?'selected':''}>제목</option><option value="rating" ${libraryFilter.sort==='rating'?'selected':''}>내 평점</option><option value="year" ${libraryFilter.sort==='year'?'selected':''}>개봉연도</option></select><div class="view-toggle"><button class="${libraryView==='grid'?'is-active':''}" data-library-view="grid" aria-label="그리드 보기">${icon('grid')}</button><button class="${libraryView==='list'?'is-active':''}" data-library-view="list" aria-label="목록 보기">${icon('list')}</button></div></div>`;}
  function libraryListRows(list){return `<div class="library-list">${list.map(m=>{const l=lib(m.id);const last=[...state.logs].reverse().find(x=>String(x.movieId)===String(m.id));return `<div class="library-row" data-movie="${m.id}" tabindex="0"><img src="${escapeHtml(poster(m))}" alt=""><div><div class="library-row-title">${escapeHtml(m.title)}</div><div class="library-row-sub">${escapeHtml(m.director||'')} · ${genreNames(m).slice(0,2).map(escapeHtml).join(' · ')}</div></div><div class="library-row-cell">${m.year||'—'}</div><div class="library-row-cell rating">${l?.rating?`★ ${l.rating}`:'—'}</div><div class="library-row-cell">${last?formatDate(last.watchedAt):'—'}</div><div class="library-row-cell">${availableOnMine(m)?'내 구독에서 가능':isInTheatres(m)?'극장 상영':'—'}</div></div>`;}).join('')}</div>`;}
  function listPage(title,summary,list){const filtered=filterLibrary(list);return `${libraryHeader(title,`${summary} · ${filtered.length}/${list.length}`)}${libraryToolbar(list)}${filtered.length?(libraryView==='grid'?`<div class="library-grid">${filtered.map(m=>card(m,'library')).join('')}</div>`:libraryListRows(filtered)):`<div class="empty-state"><b>조건에 맞는 영화가 없습니다.</b><span>필터를 바꾸거나 영화를 더 저장해보세요.</span></div>`}`;}
  function renderLibrary(){const content=document.getElementById('libraryContent');if(!content)return;if(!isSignedIn()){content.innerHTML=gateHtml('Library');document.getElementById('libraryCount').textContent='0';return;}document.getElementById('libraryCount').textContent=allSavedMovies().length;renderCollectionsSide();document.querySelectorAll('[data-library]').forEach(b=>b.classList.toggle('is-active',b.dataset.library===libraryMode));if(libraryMode==='home')content.innerHTML=renderLibraryHome();else if(libraryMode==='all')content.innerHTML=listPage('All Films','저장한 전체 영화',allSavedMovies());else if(libraryMode==='watchlist')content.innerHTML=listPage('Watchlist','보고 싶은 영화',allSavedMovies().filter(m=>lib(m.id)?.watchlist));else if(libraryMode==='favorites')content.innerHTML=listPage('Favorites','Favorite로 표시한 영화',allSavedMovies().filter(m=>lib(m.id)?.favorite));else if(libraryMode==='collections')content.innerHTML=`${libraryHeader('Collections','영화를 내 방식으로 묶어 관리합니다.')}<div class="collection-grid">${collectionCards()}</div>`;else if(libraryMode==='dynamic:my-streaming')content.innerHTML=listPage('Watchlist · 내 구독','지금 내 구독 서비스에서 볼 수 있는 Watchlist',watchlistAvailable());else if(libraryMode.startsWith('collection:')){const c=state.collections.find(x=>x.id===libraryMode.split(':')[1]);content.innerHTML=c?listPage(c.name,'직접 만든 컬렉션',c.movieIds.map(movie).filter(Boolean)):renderLibraryHome();}}

  function profileCounts(){return{films:Object.keys(state.library).length,ratings:Object.values(state.library).filter(x=>x.rating).length,reviews:Object.values(state.library).filter(x=>x.review).length,collections:state.collections.length};}
  function renderProfileCard(){const el=document.getElementById('profileCard');if(!el)return;if(!isSignedIn()){el.innerHTML='';return;}const counts=profileCounts(),recent=latestUniqueMovies()[0],name=state.profile.name||currentUser?.user_metadata?.full_name||currentUser?.email?.split('@')[0]||'KINOSIS User',initial=name[0]?.toUpperCase()||'K';el.innerHTML=`<section class="profile-hero"><div class="profile-cover">${recent?`<img src="${escapeHtml(backdrop(recent))}" alt="">`:''}</div><div class="profile-main"><div class="profile-identity"><div class="profile-left"><div class="profile-avatar">${escapeHtml(initial)}</div><div class="profile-copy"><h1>${escapeHtml(name)}</h1><p>${escapeHtml(state.profile.bio||'')}</p><p class="profile-email">${escapeHtml(currentUser?.email||'')}</p></div></div><button class="secondary-button" id="editProfile">${icon('edit')} 프로필 수정</button></div><div class="profile-counts"><div class="profile-count"><strong>${counts.films}</strong><span>영화</span></div><div class="profile-count"><strong>${counts.ratings}</strong><span>평가</span></div><div class="profile-count"><strong>${counts.reviews}</strong><span>코멘트</span></div><div class="profile-count"><strong>${counts.collections}</strong><span>컬렉션</span></div></div></div></section>`;}
  function recentReviews(){return allSavedMovies().filter(m=>lib(m.id)?.review).sort((a,b)=>String(lib(b.id)?.savedAt||'').localeCompare(String(lib(a.id)?.savedAt||'')));}
  function reviewRows(list){return `<div class="review-list">${list.map(m=>`<article class="review-row" data-movie="${m.id}"><img src="${escapeHtml(poster(m))}" alt=""><div><div class="review-title">${escapeHtml(m.title)}</div><div class="review-meta">${m.year||'—'} · ${escapeHtml(m.director||'')}</div><div class="review-text">${escapeHtml(lib(m.id)?.review||'')}</div></div><div class="rating-value">${lib(m.id)?.rating?`★ ${lib(m.id).rating}`:''}</div></article>`).join('')}</div>`;}
  function diaryRows(){return `<div class="diary-list">${latestLogs().map(l=>{const m=movie(l.movieId);if(!m)return'';return `<article class="diary-row" data-movie="${m.id}"><img src="${escapeHtml(poster(m))}" alt=""><div><div class="review-title">${escapeHtml(m.title)}</div><div class="review-meta">${formatDate(l.watchedAt)}${l.review?` · ${escapeHtml(l.review)}`:''}</div></div><div class="rating-value">${l.rating?`★ ${l.rating}`:''}</div></article>`;}).join('')}</div>`;}
  function calendarHtml(){const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=first.getDay(),logsBy={};for(const l of state.logs){if(!String(l.watchedAt).startsWith(`${y}-${String(m+1).padStart(2,'0')}`))continue;(logsBy[l.watchedAt]||(logsBy[l.watchedAt]=[])).push(l);}let cells='';for(let i=0;i<offset;i++)cells+='<div class="calendar-cell"></div>';for(let d=1;d<=days;d++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,logs=logsBy[date]||[],firstLog=logs[0],mov=firstLog?movie(firstLog.movieId):null;cells+=`<div class="calendar-cell ${date===isoDate(new Date())?'today':''}"><span class="day-number">${d}</span>${mov?`<img class="calendar-poster" src="${escapeHtml(poster(mov))}" alt="${escapeHtml(mov.title)}">`:''}${logs.length>1?`<span class="calendar-count">+${logs.length-1}</span>`:''}</div>`;}return `<div class="calendar-head"><h2>${y}년 ${m+1}월</h2><div class="calendar-controls"><button class="secondary-button" data-cal="prev">‹</button><button class="secondary-button" data-cal="next">›</button></div></div><div class="calendar-grid">${['일','월','화','수','목','금','토'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${cells}</div>`;}
  function statsHtml(){const films=allSavedMovies(),ratings=films.map(m=>lib(m.id)?.rating).filter(Boolean),avg=ratings.length?(ratings.reduce((a,b)=>a+b,0)/ratings.length).toFixed(2):'—',hours=Math.round(state.logs.reduce((s,l)=>s+(movie(l.movieId)?.runtime||0),0)/60),dist=[5,4.5,4,3.5,3,2.5,2,1.5,1,.5].map(v=>({v,n:ratings.filter(x=>x===v).length})),max=Math.max(1,...dist.map(x=>x.n));return `<div class="stat-grid"><div class="stat-card"><strong>${state.logs.length}</strong><span>감상 기록</span></div><div class="stat-card"><strong>${hours}h</strong><span>기록된 러닝타임</span></div><div class="stat-card"><strong>${avg}</strong><span>평균 평점</span></div></div><div class="my-section"><h2>평점 분포</h2><div class="rating-bars">${dist.map(x=>`<div class="rating-bar"><span>★ ${x.v}</span><div class="rating-track"><div class="rating-fill" style="width:${x.n/max*100}%"></div></div><b>${x.n}</b></div>`).join('')}</div></div>`;}
  function settingsHtml(){const syncClass=syncState.status==='online'?'online':syncState.status==='offline'?'offline':'pending';return `<div class="settings-grid"><section class="settings-card"><h3>구독 중인 서비스</h3><p>Discover와 Library에서 내 구독으로 볼 수 있는 영화를 강조합니다.</p><div class="subscription-grid">${PROVIDERS.map(p=>`<div class="subscription"><span>${escapeHtml(p.label)}</span><button data-subscription="${escapeHtml(p.key)}">${isSubscriptionEnabled(p.key)?'구독 중':'등록'}</button></div>`).join('')}</div></section><section class="settings-card"><h3>Cloud Sync</h3><p><span class="sync-pill"><span class="sync-dot ${syncClass}"></span>${escapeHtml(syncState.status.toUpperCase())}</span><br>${escapeHtml(currentUser?.email||'')}<br>Last sync · ${formatDateTime(state.meta?.lastSyncedAt)}</p><button class="secondary-button" id="syncNowButton">지금 동기화</button><button class="secondary-button" id="accountExportButton">내 데이터 내보내기</button><button class="secondary-button" id="signOutButton">로그아웃</button></section>${isAdmin()?`<section class="settings-card"><h3>KINOSIS Admin</h3><p>Discover / Arthouse 기획전을 편집하고 공개 상태를 관리합니다.</p><button class="primary-button" id="openAdminButton">Curation Studio 열기</button></section>`:''}<section class="settings-card"><h3>Data & Credits</h3><p>TMDB, JustWatch via TMDB, Supabase 사용 정보와 데이터 상태를 확인합니다.</p><button class="secondary-button" id="openAboutFromSettings">Data sources</button></section></div>`;}
  function renderMy(){const content=document.getElementById('myContent');if(!content)return;if(!isSignedIn()){document.getElementById('profileCard').innerHTML='';content.innerHTML=gateHtml('MY');return;}renderProfileCard();document.querySelectorAll('[data-my]').forEach(b=>b.classList.toggle('is-active',b.dataset.my===myMode));if(myMode==='overview'){const recent=latestUniqueMovies(),reviews=recentReviews();content.innerHTML=`${recent.length?rowSection('최근 본 영화','내 최근 감상 기록.',recent,8,'library'):''}${reviews.length?`<section class="my-section"><h2>최근 코멘트</h2>${reviewRows(reviews.slice(0,5))}</section>`:''}<section class="my-section"><h2>이번 달</h2>${calendarHtml()}</section>`;}else if(myMode==='diary')content.innerHTML=`<section class="my-section"><h2>Diary</h2>${state.logs.length?diaryRows():'<div class="empty-state"><b>아직 감상 기록이 없습니다.</b></div>'}</section>`;else if(myMode==='reviews')content.innerHTML=`<section class="my-section"><h2>Reviews</h2>${recentReviews().length?reviewRows(recentReviews()):'<div class="empty-state"><b>아직 코멘트가 없습니다.</b></div>'}</section>`;else if(myMode==='calendar')content.innerHTML=`<section class="my-section">${calendarHtml()}</section>`;else if(myMode==='stats')content.innerHTML=`<section class="my-section">${statsHtml()}</section>`;else content.innerHTML=`<section class="my-section">${settingsHtml()}</section>`;}

  function detailProviderGroups(m){const groups={subscription:[],free:[],ads:[],rent:[],buy:[]};(m.providers||[]).forEach(p=>(groups[p.type]||(groups[p.type]=[])).push(p));const group=(key,label)=>groups[key]?.length?`<div class="provider-group"><h4>${label}</h4><div class="providers">${groups[key].map(p=>`<span class="provider-pill ${key==='subscription'&&isSubscribedProvider(p.name)?'owned':''}">${p.logoUrl?`<img class="provider-inline-logo" src="${escapeHtml(p.logoUrl)}" alt="">`:''}${escapeHtml(providerConfigForName(p.name)?.label||p.name)} · ${escapeHtml(providerTypeLabel(key))}</span>`).join('')}</div></div>`:'';return group('subscription','SUBSCRIPTION')+group('free','FREE')+group('ads','WITH ADS')+group('rent','RENT')+group('buy','BUY');}
  function relatedMovies(m){const genres=new Set(genreNames(m));return(CATALOG.movies||[]).filter(x=>String(x.id)!==String(m.id)&&genreNames(x).some(g=>genres.has(g))).slice(0,10);}
  function renderMoviePage(m){if(!m)return;const l=lib(m.id),art=artInfo(m),last=[...state.logs].reverse().find(x=>String(x.movieId)===String(m.id));document.getElementById('moviePage').innerHTML=`<div class="movie-page-back"><button data-movie-back>${icon('back')} ${previousView==='arthouse'?'Arthouse':previousView==='library'?'Library':previousView==='my'?'My':'Discover'}로 돌아가기</button></div><section class="detail-hero"><img class="detail-hero-bg" src="${escapeHtml(backdrop(m))}" alt=""><div class="detail-hero-inner"><img class="detail-poster" src="${escapeHtml(poster(m))}" alt="${escapeHtml(m.title)} 포스터"><div><p class="eyebrow">${isInTheatres(m)?'IN THEATRES':isArthouse(m)?'ARTHOUSE':'FILM'}</p><h1 class="detail-title">${escapeHtml(m.title)}</h1>${m.originalTitle&&m.originalTitle!==m.title?`<div class="detail-original">${escapeHtml(m.originalTitle)}</div>`:''}<div class="detail-meta"><span>${escapeHtml(m.director||'Director —')}</span><span>·</span><span>${m.year||'—'}</span>${m.runtime?`<span>·</span><span>${fmtRuntime(m.runtime)}</span>`:''}<span>·</span><span>TMDB ★ ${m.voteAverage?Number(m.voteAverage).toFixed(1):'—'}</span></div><div class="detail-actions"><button class="primary-button detail-action" data-action="save" data-id="${m.id}">${l?'✓ Library':'＋ Library'}</button><button class="secondary-button detail-action" data-action="log" data-id="${m.id}">LOG</button><button class="secondary-button detail-action" data-action="watchlist" data-id="${m.id}">${l?.watchlist?'✓ Watchlist':'＋ Watchlist'}</button><button class="secondary-button detail-action" data-action="favorite" data-id="${m.id}">${l?.favorite?'♥ Favorite':'♡ Favorite'}</button><button class="secondary-button detail-action" data-action="collection-add" data-id="${m.id}">＋ Collection</button></div></div></div></section><div class="detail-body"><div><section class="detail-block"><h2>About</h2><p class="detail-overview">${escapeHtml(m.overview||'줄거리 정보가 없습니다.')}</p><div class="detail-facts"><div class="detail-fact"><span>Director</span><b>${escapeHtml(m.director||'—')}</b></div><div class="detail-fact"><span>Genres</span><b>${genreNames(m).map(escapeHtml).join(' · ')||'—'}</b></div>${m.cast?.length?`<div class="detail-fact"><span>Cast</span><b>${m.cast.slice(0,8).map(x=>escapeHtml(x.name||x)).join(' · ')}</b></div>`:''}</div>${art.isArt?`<div class="arthouse-note"><b>ARTHOUSE CANDIDATE</b><div>${(art.reasons||[]).map(r=>`<span class="art-reason">${escapeHtml(r)}</span>`).join('')}</div></div>`:''}</section>${relatedMovies(m).length?`<section class="my-section">${rowSection('비슷한 영화','장르 기준으로 이어서 볼 만한 작품.',relatedMovies(m),9)}</section>`:''}</div><aside><section class="detail-block"><h2>Where to Watch</h2><div class="provider-groups">${detailProviderGroups(m)||'<div class="activity-empty">현재 KR 제공처 정보가 없습니다.</div>'}</div><p class="activity-empty">JustWatch via TMDB · 실제 제공 여부와 요금은 각 서비스에서 최종 확인하세요.</p></section><section class="detail-block"><h2>My Activity</h2>${isSignedIn()?(l?`<div class="my-activity"><div class="activity-rating">${l.rating?`★ ${l.rating}`:'평점 없음'}</div>${l.review?`<div class="activity-review">${escapeHtml(l.review)}</div>`:''}<div class="activity-empty">${last?`최근 감상 · ${formatDate(last.watchedAt)}`:'Library에 저장됨'}</div></div>`:'<div class="activity-empty">아직 이 영화에 대한 기록이 없습니다.</div>'):'<div class="activity-empty">로그인하면 평점, Diary, Watchlist와 컬렉션을 기록할 수 있습니다.</div>'}</section></aside></div>`;}
  async function openMovie(id){let m=movie(id);if(!m)return;previousView=activeView==='movie'?previousView:activeView;detailMovieId=String(id);setView('movie',{skipGate:true,keepScroll:false});document.getElementById('moviePage').innerHTML=`<div class="detail-loading"><div class="loading-ring"></div><b>${escapeHtml(m.title)}</b><span>상세정보를 불러오는 중…</span></div>`;m=await ensureMovieDetail(id,{persist:!!lib(id)})||m;renderMoviePage(m);}

  function localSearch(q){const lower=q.toLocaleLowerCase('ko-KR');return(CATALOG.movies||[]).filter(m=>[m.title,m.originalTitle,m.director].filter(Boolean).join(' ').toLocaleLowerCase('ko-KR').includes(lower));}
  function relevance(m,q){const x=q.toLocaleLowerCase('ko-KR'),title=String(m.title||'').toLocaleLowerCase('ko-KR'),orig=String(m.originalTitle||'').toLocaleLowerCase('ko-KR'),director=String(m.director||'').toLocaleLowerCase('ko-KR');let s=0;if(title===x||orig===x)s+=100;if(title.startsWith(x)||orig.startsWith(x))s+=55;if(title.includes(x)||orig.includes(x))s+=30;if(director.includes(x))s+=12;if(CATALOG.movies?.some(c=>String(c.id)===String(m.id)))s+=5;s+=Math.min(10,Number(m.voteCount||0)/10000);return s;}
  function combinedSearch(q){const local=localSearch(q),live=liveSearchState.query===q?liveSearchState.results:[],map=new Map();for(const m of[...live,...local])map.set(String(m.id),m);return[...map.values()].sort((a,b)=>relevance(b,q)-relevance(a,q));}
  function renderSearch(q=''){const el=document.getElementById('searchResults');if(!el)return;const query=q.trim();if(!query){const rec=uniqueById(CATALOG.sections?.trending||[]).slice(0,8);el.innerHTML=rec.map(searchRow).join('');return;}const results=combinedSearch(query);const status=liveSearchState.status==='loading'?'<span>TMDB 검색 중…</span>':liveSearchState.status==='error'?'<span>Live search unavailable · local results</span>':'';el.innerHTML=status+results.slice(0,20).map(searchRow).join('')+(results.length?'':'<div class="empty-state"><b>검색 결과가 없습니다.</b></div>');}
  function searchRow(m){const action=searchPurpose==='curation'?`<button class="secondary-button" data-curation-add="${m.id}">기획전에 추가</button>`:`${isSignedIn()?`<button class="secondary-button" data-action="save" data-id="${m.id}">${lib(m.id)?'✓ Saved':'＋ Save'}</button><button class="secondary-button" data-action="log" data-id="${m.id}">LOG</button>`:''}`;return `<article class="search-result" data-movie="${m.id}" tabindex="0"><img src="${escapeHtml(poster(m))}" alt=""><div><h3>${escapeHtml(m.title)}</h3><p>${m.originalTitle&&m.originalTitle!==m.title?`${escapeHtml(m.originalTitle)} · `:''}${m.year||'—'}${m.director?` · ${escapeHtml(m.director)}`:''}</p></div><div class="search-actions">${action}</div></article>`;}
  async function runLiveSearch(query,serial){if(!canUseLiveApi()||query.length<LIVE_SEARCH_MIN_CHARS)return;if(searchAbort)searchAbort.abort();searchAbort=new AbortController();liveSearchState={query,status:'loading',results:[],message:''};renderSearch(query);try{const results=await fetchLiveSearch(query,{signal:searchAbort.signal});if(serial!==searchSerial)return;liveSearchState={query,status:'done',results,message:''};}catch(error){if(error?.name==='AbortError'||serial!==searchSerial)return;liveSearchState={query,status:'error',results:[],message:error.message||'Live search failed'};}renderSearch(query);}
  function queueSearch(value){const q=value.trim();clearTimeout(searchTimer);const serial=++searchSerial;liveSearchState=q===liveSearchState.query?liveSearchState:{query:q,status:'idle',results:[],message:''};renderSearch(q);if(searchComposing||q.length<LIVE_SEARCH_MIN_CHARS||!canUseLiveApi())return;searchTimer=setTimeout(()=>runLiveSearch(q,serial),LIVE_SEARCH_DEBOUNCE);}
  function openSearch(purpose='normal'){searchPurpose=purpose;document.getElementById('searchContext').textContent=purpose==='curation'?'영화를 검색해 현재 기획전에 추가합니다.':'KINOSIS 카탈로그와 TMDB 전체 DB를 함께 검색합니다.';UI.showDialog('searchDialog');const input=document.getElementById('searchInput');input.value='';liveSearchState={query:'',status:'idle',results:[],message:''};renderSearch('');setTimeout(()=>input.focus(),50);}

  async function saveMovie(id){if(!requireAuth())return;const existed=!!lib(id);let m=movie(id);if(!m)return;m=await ensureMovieDetail(id,{persist:true})||m;rememberMovie(m,{persist:true});ensureLib(id);saveState();renderAll();if(activeView==='movie')renderMoviePage(m);UI.toast(existed?'이미 Library에 있습니다.':'Library에 추가했습니다.');}
  async function openLog(id){if(!requireAuth())return;let m=movie(id);if(!m)return;m=await ensureMovieDetail(id,{persist:true})||m;rememberMovie(m,{persist:true});saveState();document.getElementById('logMovieId').value=String(id);document.getElementById('logMovieTitle').textContent=m.title;document.getElementById('logDate').value=isoDate(new Date());const l=lib(id);document.getElementById('logRating').value=l?.rating||'';document.getElementById('logReview').value=l?.review||'';document.getElementById('logFavorite').checked=!!l?.favorite;UI.showDialog('logDialog');}
  function toggleWatchlist(id){if(!requireAuth())return;const m=movie(id);if(m)rememberMovie(m,{persist:true});const l=ensureLib(id);l.watchlist=!l.watchlist;saveState();renderAll();if(activeView==='movie')renderMoviePage(movie(id));UI.toast(l.watchlist?'Watchlist에 추가했습니다.':'Watchlist에서 제거했습니다.');}
  function toggleFavorite(id){if(!requireAuth())return;const m=movie(id);if(m)rememberMovie(m,{persist:true});const l=ensureLib(id);l.favorite=!l.favorite;saveState();renderAll();if(activeView==='movie')renderMoviePage(movie(id));UI.toast(l.favorite?'Favorite로 표시했습니다.':'Favorite를 해제했습니다.');}
  async function newCollection(){if(!requireAuth())return;const a=await UI.ask({eyebrow:'COLLECTION',title:'새 컬렉션',message:'영화를 묶을 이름을 정하세요.',input:{label:'컬렉션 이름',placeholder:'예: 한국 뉴웨이브'},confirmText:'만들기'});if(!a.confirmed||!a.input?.trim())return;state.collections.push({id:'col-'+Date.now(),name:a.input.trim(),type:'manual',movieIds:[]});saveState();libraryMode='collections';renderAll();}
  async function addToCollection(id){if(!requireAuth())return;if(!state.collections.length){await newCollection();if(!state.collections.length)return;}const a=await UI.ask({eyebrow:'COLLECTION',title:'컬렉션에 추가',message:movie(id)?.title||'',select:{label:'컬렉션',options:state.collections.map(c=>({value:c.id,label:c.name}))},confirmText:'추가'});if(!a.confirmed)return;const c=state.collections.find(x=>x.id===a.select);if(!c)return;if(!c.movieIds.includes(String(id)))c.movieIds.push(String(id));const m=movie(id);if(m)rememberMovie(m,{persist:true});ensureLib(id);saveState();renderAll();UI.toast(`${c.name}에 추가했습니다.`);}
  function editProfile(){document.getElementById('profileName').value=state.profile.name||'';document.getElementById('profileBio').value=state.profile.bio||'';UI.showDialog('profileDialog');}

  async function refreshCurations(){if(!CLOUD)return;curationStatus='loading';try{const includeDrafts=isAdmin();curations=await CLOUD.listCurations({includeDrafts});curations.forEach(c=>c.items?.forEach(x=>rememberMovie(x.movie)));curationStatus='ready';}catch(error){console.warn('curations:',error);curationStatus='offline';curations=[];}if(activeView==='discover')renderDiscover();if(activeView==='arthouse')renderArthouse();}
  function blankCuration(){return{id:null,slug:'',title:'',subtitle:'',description:'',surface:'arthouse',type:'directors_archive',status:'draft',sort_order:0,items:[]};}
  function renderAdmin(){const el=document.getElementById('adminContent');if(!el)return;if(!isAdmin()){el.innerHTML=gateHtml('Admin');return;}const list=curations,selected=adminDraft||(adminSelectedId?list.find(c=>String(c.id)===String(adminSelectedId)):null);el.innerHTML=`<header class="admin-header"><div><p class="eyebrow">KINOSIS ADMIN</p><h1>Curation Studio</h1><p class="activity-empty">Discover와 Arthouse의 기획전을 직접 편집합니다.</p></div><button class="primary-button" id="newCurationButton">＋ New Curation</button></header><div class="admin-shell"><aside class="admin-list">${list.length?list.map(c=>`<button class="admin-list-item ${String(c.id)===String(adminSelectedId)?'is-active':''}" data-admin-curation="${c.id}"><b>${escapeHtml(c.title)}</b><span>${escapeHtml(c.surface)} · ${escapeHtml(c.status)}</span></button>`).join(''):'<div class="activity-empty">아직 기획전이 없습니다.</div>'}</aside><section class="admin-editor">${selected?adminEditor(selected):'<div class="empty-state"><b>기획전을 선택하거나 새로 만드세요.</b></div>'}</section></div>`;}
  function adminEditor(c){return `<form id="curationForm"><input type="hidden" id="curationId" value="${escapeHtml(c.id||'')}"><div class="admin-form-grid"><label>Title<input id="curationTitle" value="${escapeHtml(c.title||'')}" required></label><label>Slug<input id="curationSlug" value="${escapeHtml(c.slug||'')}" placeholder="directors-archive-petzold"></label><label class="full">Subtitle<input id="curationSubtitle" value="${escapeHtml(c.subtitle||'')}"></label><label class="full">Description<textarea id="curationDescription" rows="4">${escapeHtml(c.description||'')}</textarea></label><label>Surface<select id="curationSurface"><option value="discover" ${c.surface==='discover'?'selected':''}>Discover</option><option value="arthouse" ${c.surface==='arthouse'?'selected':''}>Arthouse</option><option value="both" ${c.surface==='both'?'selected':''}>Both</option></select></label><label>Type<select id="curationType"><option value="directors_archive" ${c.type==='directors_archive'?'selected':''}>Director's Archive</option><option value="selection" ${c.type==='selection'?'selected':''}>Selection</option><option value="theme" ${c.type==='theme'?'selected':''}>Theme</option></select></label><label>Status<select id="curationStatus"><option value="draft" ${c.status==='draft'?'selected':''}>Draft</option><option value="published" ${c.status==='published'?'selected':''}>Published</option></select></label><label>Sort order<input id="curationSort" type="number" value="${Number(c.sort_order||0)}"></label></div><div class="admin-toolbar"><div><p class="eyebrow">FILMS</p><span class="activity-empty">표시 순서를 직접 관리합니다.</span></div><button class="secondary-button" type="button" id="adminSearchMovies">${icon('search')} 영화 추가</button></div><div class="admin-movies">${(c.items||[]).map((x,i)=>{const m=x.movie||movie(x.tmdbId)||{};return `<div class="admin-movie-row"><img src="${escapeHtml(poster(m))}" alt=""><div><b>${escapeHtml(m.title||x.tmdbId)}</b><div class="activity-empty">${m.year||''}</div></div><div class="admin-movie-actions"><button type="button" data-curation-move="up" data-index="${i}">↑</button><button type="button" data-curation-move="down" data-index="${i}">↓</button><button type="button" data-curation-remove="${i}">×</button></div></div>`;}).join('')}</div><div class="form-actions"><button type="button" class="secondary-button danger-button" id="deleteCurationButton" ${c.id?'':'hidden'}>삭제</button><button type="submit" class="primary-button">저장</button></div></form>`;}
  function slugify(s){return String(s||'').normalize('NFKD').toLowerCase().replace(/[^a-z0-9가-힣]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||`curation-${Date.now()}`;}
  async function addMovieToAdminCuration(id){if(!adminDraft){const base=adminSelectedId?curations.find(c=>String(c.id)===String(adminSelectedId)):blankCuration();adminDraft=JSON.parse(JSON.stringify(base||blankCuration()));}let m=movie(id);m=await ensureMovieDetail(id)||m;if(!m)return;if(!adminDraft.items.some(x=>String(x.tmdbId)===String(m.id)))adminDraft.items.push({position:adminDraft.items.length,tmdbId:String(m.id),movie:m});UI.closeDialog('searchDialog');setView('admin',{skipGate:true});renderAdmin();}
  function captureAdminDraftFromForm(){
    if(!adminDraft)return;
    const get=id=>document.getElementById(id);
    if(!get('curationTitle'))return;
    adminDraft.title=get('curationTitle').value;adminDraft.slug=get('curationSlug').value;adminDraft.subtitle=get('curationSubtitle').value;adminDraft.description=get('curationDescription').value;adminDraft.surface=get('curationSurface').value;adminDraft.type=get('curationType').value;adminDraft.status=get('curationStatus').value;adminDraft.sort_order=Number(get('curationSort').value||0);
  }
  async function saveAdminCuration(){if(!isAdmin()||!CLOUD)return;const base=adminDraft||blankCuration();const meta={id:document.getElementById('curationId').value||null,title:document.getElementById('curationTitle').value.trim(),slug:document.getElementById('curationSlug').value.trim()||slugify(document.getElementById('curationTitle').value),subtitle:document.getElementById('curationSubtitle').value.trim(),description:document.getElementById('curationDescription').value.trim(),surface:document.getElementById('curationSurface').value,type:document.getElementById('curationType').value,status:document.getElementById('curationStatus').value,sort_order:Number(document.getElementById('curationSort').value||0)};if(!meta.title)return;try{const id=await CLOUD.saveCuration(meta,base.items||[]);adminSelectedId=id;adminDraft=null;await refreshCurations();renderAdmin();UI.toast('기획전을 저장했습니다.');}catch(error){UI.toast(error.message||'기획전 저장 실패');}}

  function setView(view,{skipGate=false,keepScroll=false}={}){if(!skipGate&&(view==='library'||view==='my')&&!requireAuth(`${view==='library'?'Library':'MY'}는 로그인 후 사용할 수 있습니다.`))return;if(view==='admin'&&!isAdmin()){UI.toast('관리자 권한이 필요합니다.');return;}activeView=view;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('is-active',v.dataset.view===view));document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('is-active',b.dataset.nav===view));document.querySelectorAll('.mobile-nav-item[data-nav]').forEach(b=>b.classList.toggle('is-active',b.dataset.nav===view));if(!keepScroll)window.scrollTo({top:0,behavior:'smooth'});}
  function renderStatus(){const live=CATALOG.mode==='live';document.getElementById('dataStatusText').textContent=live?'SYNCED':'LOCAL';document.getElementById('sourceStatus').innerHTML=`Catalog: <b>${live?'LIVE API SYNC':'LOCAL DEMO'}</b><br>Updated: ${escapeHtml(CATALOG.updatedAt||'unknown')}<br>Region: ${escapeHtml(CATALOG.region||'KR')}<br>Auth: ${isSignedIn()?`SIGNED IN · ${escapeHtml(syncState.status.toUpperCase())}`:'SIGNED OUT'}<br>Role: ${escapeHtml(currentRole)}`;}
  function renderAll(){renderDiscover();renderArthouse();renderLibrary();renderMy();if(activeView==='movie'&&detailMovieId)renderMoviePage(movie(detailMovieId));if(activeView==='admin')renderAdmin();renderStatus();renderAccountChrome();}

  document.addEventListener('click',async e=>{
    const close=e.target.closest('[data-close]');if(close){UI.closeDialog(close.dataset.close);return;}
    const nav=e.target.closest('[data-nav]');if(nav){setView(nav.dataset.nav);return;}
    const lt=e.target.closest('[data-library]');if(lt){libraryMode=lt.dataset.library;renderLibrary();return;}
    const mt=e.target.closest('[data-my]');if(mt){myMode=mt.dataset.my;renderMy();return;}
    const lv=e.target.closest('[data-library-view]');if(lv){libraryView=lv.dataset.libraryView;renderLibrary();return;}
    const action=e.target.closest('[data-action]');if(action){e.stopPropagation();const id=action.dataset.id,a=action.dataset.action;if(a==='save')await saveMovie(id);else if(a==='log')await openLog(id);else if(a==='watchlist')toggleWatchlist(id);else if(a==='favorite')toggleFavorite(id);else if(a==='collection-add')await addToCollection(id);return;}
    const cAdd=e.target.closest('[data-curation-add]');if(cAdd){e.stopPropagation();await addMovieToAdminCuration(cAdd.dataset.curationAdd);return;}
    const mov=e.target.closest('[data-movie]');if(mov){await openMovie(mov.dataset.movie);return;}
    if(e.target.closest('[data-movie-back]')){setView(previousView,{skipGate:true});return;}
    const collection=e.target.closest('[data-collection],[data-collection-card]');if(collection){libraryMode=`collection:${collection.dataset.collection||collection.dataset.collectionCard}`;setView('library');renderLibrary();return;}
    if(e.target.closest('[data-dynamic]')){libraryMode='dynamic:my-streaming';setView('library');renderLibrary();return;}
    if(e.target.closest('#searchTrigger')||e.target.closest('#mobileSearch')||e.target.closest('#librarySearchButton')){openSearch();return;}
    if(e.target.closest('[data-open-auth]')){UI.showDialog('authDialog');return;}
    const authProvider=e.target.closest('[data-auth-provider]');if(authProvider){const msg=document.getElementById('authMessage');msg.textContent='로그인 페이지로 이동합니다…';try{await CLOUD?.signInOAuth(authProvider.dataset.authProvider);}catch(error){msg.textContent=error.message||'로그인 설정을 확인하세요.';msg.classList.add('is-error');}return;}
    if(e.target.closest('#topAccountButton')){if(isSignedIn()){myMode='settings';setView('my');renderMy();}else UI.showDialog('authDialog');return;}
    const sub=e.target.closest('[data-subscription]');if(sub){if(!requireAuth())return;const p=sub.dataset.subscription,on=isSubscriptionEnabled(p);state.subscriptions=on?state.subscriptions.filter(x=>normalizeProviderName(x)!==normalizeProviderName(p)):[...(state.subscriptions||[]),p];saveState();renderAll();return;}
    const cal=e.target.closest('[data-cal]');if(cal){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+(cal.dataset.cal==='next'?1:-1),1);renderMy();return;}
    if(e.target.closest('#newCollectionButton')){await newCollection();return;}
    if(e.target.closest('#editProfile')){editProfile();return;}
    if(e.target.closest('#syncNowButton')){await pushCloudState();return;}
    if(e.target.closest('#signOutButton')){await CLOUD?.signOut();return;}
    if(e.target.closest('#accountExportButton')||e.target.closest('#exportButton')){exportData();return;}
    if(e.target.closest('#aboutButton')||e.target.closest('#dataStatusButton')||e.target.closest('#openAboutFromSettings')){UI.showDialog('aboutDialog');return;}
    if(e.target.closest('#openAdminButton')){setView('admin',{skipGate:true});renderAdmin();return;}
    if(e.target.closest('#newCurationButton')){adminSelectedId=null;adminDraft=blankCuration();renderAdmin();return;}
    const adminItem=e.target.closest('[data-admin-curation]');if(adminItem){adminSelectedId=adminItem.dataset.adminCuration;adminDraft=JSON.parse(JSON.stringify(curations.find(c=>String(c.id)===String(adminSelectedId))||blankCuration()));renderAdmin();return;}
    if(e.target.closest('#adminSearchMovies')){captureAdminDraftFromForm();searchPurpose='curation';openSearch('curation');return;}
    const cRemove=e.target.closest('[data-curation-remove]');if(cRemove){captureAdminDraftFromForm();adminDraft.items.splice(Number(cRemove.dataset.curationRemove),1);renderAdmin();return;}
    const cMove=e.target.closest('[data-curation-move]');if(cMove){captureAdminDraftFromForm();const i=Number(cMove.dataset.index),j=cMove.dataset.curationMove==='up'?i-1:i+1;if(j>=0&&j<adminDraft.items.length)[adminDraft.items[i],adminDraft.items[j]]=[adminDraft.items[j],adminDraft.items[i]];renderAdmin();return;}
    if(e.target.closest('#deleteCurationButton')){const a=await UI.ask({eyebrow:'CURATION',title:'기획전을 삭제할까요?',message:'공개 중인 기획전이라면 즉시 Discover/Arthouse에서 사라집니다.',confirmText:'삭제',danger:true});if(a.confirmed){try{await CLOUD.deleteCuration(adminDraft.id);adminDraft=null;adminSelectedId=null;await refreshCurations();renderAdmin();UI.toast('삭제했습니다.');}catch(error){UI.toast(error.message||'삭제 실패');}}return;}
  });

  document.addEventListener('input',e=>{if(e.target.id==='libraryQuery'){libraryFilter.q=e.target.value;clearTimeout(libraryQueryTimer);const pos=e.target.selectionStart||libraryFilter.q.length;libraryQueryTimer=setTimeout(()=>{renderLibrary();const input=document.getElementById('libraryQuery');if(input){input.focus();input.setSelectionRange(Math.min(pos,input.value.length),Math.min(pos,input.value.length));}},180);}});
  document.addEventListener('change',e=>{const map={libraryStatus:'status',libraryAvailability:'availability',libraryGenre:'genre',libraryDecade:'decade',libraryArthouse:'arthouse',librarySort:'sort'};if(map[e.target.id]){libraryFilter[map[e.target.id]]=e.target.value;renderLibrary();}});
  document.getElementById('searchInput').addEventListener('compositionstart',()=>{searchComposing=true;});
  document.getElementById('searchInput').addEventListener('compositionend',e=>{searchComposing=false;queueSearch(e.target.value);});
  document.getElementById('searchInput').addEventListener('input',e=>{if(!searchComposing)queueSearch(e.target.value);});
  document.getElementById('emailAuthForm').addEventListener('submit',async e=>{e.preventDefault();const email=document.getElementById('authEmail').value.trim(),msg=document.getElementById('authMessage');if(!email)return;msg.textContent='로그인 링크를 보내는 중…';msg.classList.remove('is-error');try{await CLOUD.sendMagicLink(email);msg.textContent='이메일을 확인하세요.';}catch(error){msg.textContent=error.message||'요청 실패';msg.classList.add('is-error');}});
  document.getElementById('logForm').addEventListener('submit',e=>{e.preventDefault();if(!requireAuth())return;const id=document.getElementById('logMovieId').value,watchedAt=document.getElementById('logDate').value,rating=document.getElementById('logRating').value,review=document.getElementById('logReview').value.trim(),favorite=document.getElementById('logFavorite').checked;if(!id||!watchedAt)return;const m=movie(id);if(m)rememberMovie(m,{persist:true});const l=ensureLib(id);l.watched=true;l.watchlist=false;l.favorite=favorite;if(rating)l.rating=Number(rating);l.review=review;state.logs.push({id:'log-'+Date.now(),movieId:String(id),watchedAt,rating:rating?Number(rating):null,review});saveState();UI.closeDialog('logDialog');renderAll();if(activeView==='movie')renderMoviePage(movie(id));UI.toast('감상 기록을 저장했습니다.');});
  document.getElementById('profileForm').addEventListener('submit',e=>{e.preventDefault();state.profile.name=document.getElementById('profileName').value.trim();state.profile.bio=document.getElementById('profileBio').value.trim();saveState();UI.closeDialog('profileDialog');renderAll();});
  document.addEventListener('submit',async e=>{if(e.target.id==='curationForm'){e.preventDefault();await saveAdminCuration();}});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();}if((e.key==='Enter'||e.key===' ')&&document.activeElement?.matches('.movie-card,.editorial-movie-card,.search-result')){e.preventDefault();openMovie(document.activeElement.dataset.movie);}});

  function exportData(){if(!requireAuth())return;state.settings.lastExportAt=new Date().toISOString();saveState();const blob=new Blob([JSON.stringify({version:3,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`kinosis-${isoDate(new Date())}.json`;a.click();URL.revokeObjectURL(a.href);UI.toast('내 데이터를 내보냈습니다.');}
  async function handleImport(e){if(!requireAuth())return;const file=e.target.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed.state?.library)throw new Error('invalid');state=mergeImport(state,parsed.state);Object.values(state.movieCache||{}).forEach(m=>rememberMovie(m));saveState();renderAll();UI.closeDialog('aboutDialog');UI.toast('데이터를 가져왔습니다.');}catch{UI.toast('KINOSIS 데이터 파일을 읽지 못했습니다.');}e.target.value='';}
  document.getElementById('importInput').addEventListener('change',handleImport);

  let hydratedUserId=null;
  if(CLOUD){
    CLOUD.onChange(async({user,error,event})=>{authReady=true;currentUser=user||null;if(error)syncState={status:'offline',lastSyncedAt:null,message:error.message||'Auth unavailable'};if(currentUser){UI.closeDialog('authDialog');if(hydratedUserId!==currentUser.id||event==='SIGNED_IN'){hydratedUserId=currentUser.id;await hydrateSignedInUser();}else renderAll();}else{hydratedUserId=null;currentRole='guest';suppressCloudSync=true;state=initialState();syncState={status:'guest',lastSyncedAt:null,message:''};renderAll();setView('discover',{skipGate:true});}});
    CLOUD.init().then(async()=>{authReady=true;if(!currentUser)await refreshCurations();}).catch(()=>{});
  }else authReady=true;
  window.addEventListener('online',()=>{if(isSignedIn()&&state.meta?.dirtySince)pushCloudState();});
  window.addEventListener('offline',()=>{if(isSignedIn()){syncState.status='offline';renderAccountChrome();}});

  renderAll();setView('discover',{skipGate:true});
  if((location.protocol==='http:'||location.protocol==='https:')&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});
})();
